/* ─── GLOSSARY ─────────────────────────────────────────────────────────
   Insider shorthand a first-year won't know. Both views render the first use
   of each term in a block as <abbr title="…">, so the text stays tight and
   every acronym explains itself on hover. Definitions, not claims: no `src`. */
const GLOSSARY = {
  'A&D': 'aerospace and defense',
  'C2': 'command and control: software and systems for directing forces',
  'NGC2': 'Next Generation Command and Control, the Army\'s C2 modernisation program',
  'UAS': 'uncrewed aircraft systems: drones',
  'EW': 'electronic warfare: jamming, sensing and protecting radio spectrum',
  'RF': 'radio frequency',
  'SRM': 'solid rocket motor',
  'AP': 'ammonium perchlorate, the oxidiser in solid rocket propellant',
  'AAP': 'Army Ammunition Plant',
  'IC': 'the US intelligence community',
  'OSC': 'the Pentagon\'s Office of Strategic Capital, which lends to supply-chain companies',
  'DIU': 'Defense Innovation Unit: the Pentagon\'s fast-contracting door for commercial tech',
  'SDA': 'Space Development Agency (US Space Force)',
  'NRO': 'National Reconnaissance Office: builds and runs US spy satellites',
  'SOCOM': 'US Special Operations Command',
  'DARPA': 'Defense Advanced Research Projects Agency',
  'AFWERX': 'the Air Force\'s innovation and small-business arm',
  'AFRL': 'Air Force Research Laboratory',
  'IBAS': 'Industrial Base Analysis and Sustainment, a Pentagon program that funds weak links in the supply chain',
  'DLA': 'Defense Logistics Agency',
  'EXIM': 'Export-Import Bank of the United States',
  'DPA': 'Defense Production Act',
  'SBIR': 'Small Business Innovation Research: federal R&D grants and contracts for small firms',
  'STTR': 'Small Business Technology Transfer: SBIR\'s sibling for firms partnered with a research institution',
  'OTA': 'Other Transaction Authority: a fast contracting route outside standard procurement rules',
  'ITAR': 'International Traffic in Arms Regulations: US export controls on defense items',
  'CCA': 'Collaborative Combat Aircraft: uncrewed jets that fly alongside crewed fighters',
  'NSSL': 'National Security Space Launch, the program that buys launches for military satellites',
  'ULA': 'United Launch Alliance, the Boeing–Lockheed launch joint venture',
  'LEO': 'low Earth orbit',
  'VLEO': 'very low Earth orbit',
  'GEO': 'geostationary orbit',
  'AESA': 'active electronically scanned array: a modern radar with no moving dish',
  'GaN': 'gallium nitride, a chip material for high-power radar and radio',
  'FPGA': 'field-programmable gate array: a reconfigurable chip',
  'ASIC': 'application-specific integrated circuit: a custom chip',
  'MMIC': 'monolithic microwave integrated circuit: an RF chip',
  'QML': 'Qualified Manufacturers List: the approved-supplier list for military-grade chips',
  'VIM/VAR': 'vacuum induction melting / vacuum arc remelting: the furnaces that make superalloys',
  'HTPB': 'the rubbery binder that holds solid rocket propellant together',
  'RDX': 'a military high explosive',
  'HMX': 'a military high explosive',
  'SIPRI': 'Stockholm International Peace Research Institute, which ranks arms companies',
  // drone vocabulary, added 2026-10-18 (shown as a list on index.html)
  'sUAS': 'small uncrewed aircraft systems: drones under 55 lb',
  'Group 1': 'the smallest of the DoD\'s five drone size classes; Groups 1–3 are the small and tactical ones, Groups 4–5 the large ones',
  'FPV': 'first-person view: a small drone flown through a live camera feed, often carrying a warhead',
  'OWA': 'one-way attack: a drone built to strike once and be destroyed',
  'loitering munition': 'a drone that circles over an area, then dives onto a target it finds',
  'ISR': 'intelligence, surveillance and reconnaissance',
  'VTOL': 'vertical take-off and landing',
  'MTOW': 'maximum take-off weight',
  'C-UAS': 'counter-uncrewed aircraft systems: detecting and stopping drones',
  'HPM': 'high-power microwave: a directed-energy weapon that fries electronics, useful against swarms',
  'BVLOS': 'beyond visual line of sight: flying a drone farther than the operator can see',
  'Part 107': 'the FAA\'s rule for routine commercial small-drone flight, within line of sight',
  'Part 108': 'the FAA\'s proposed rule to make beyond-line-of-sight flight routine; not yet final',
  'Part 135': 'the FAA air-carrier certificate that drone delivery operators hold',
  'Remote ID': 'the FAA requirement that drones broadcast their identity and location in flight',
  'DFR': 'drone as first responder: a police or fire drone launched to a 911 call',
  'Blue UAS': 'the Pentagon\'s list of vetted drones and components, now run by DCMA',
  'Covered List': 'the FCC\'s list of equipment that cannot get new US authorization on national-security grounds',
  'Buy American': 'federal domestic-content rules; for the FCC drone exemption, at least 65% US component cost',
  'NDAA': 'National Defense Authorization Act: the annual defense policy law. "NDAA-compliant" drones avoid parts from barred Chinese firms',
  'DCMA': 'Defense Contract Management Agency',
  'DAWG': 'Defense Autonomous Warfare Group, under SOCOM; inherited Replicator',
  'JIATF-401': 'Joint Interagency Task Force 401: the Pentagon\'s counter-drone coordinator since 2025',
  'SRR': 'Short Range Reconnaissance: the Army\'s small quadcopter program',
  'PBAS': 'Purpose-Built Attritable Systems: the Army\'s FPV drone program',
  'LASSO': 'Low Altitude Stalking and Strike Ordnance: the Army\'s loitering-munition program',
  'OPF-L': 'Organic Precision Fires-Light: the Marine Corps\' squad loitering-munition program',
  'IDIQ': 'indefinite delivery, indefinite quantity: a contract vehicle with a ceiling, not guaranteed revenue',
  'CSO': 'commercial solutions opening: a fast way for the government to buy commercial technology',
  'OIRA': 'the White House office that reviews major rules before they are published',
  'SLTT': 'state, local, tribal and territorial (government)',
  'MANET': 'mobile ad-hoc network: radios that relay through each other with no tower',
  'PX4': 'an open-source drone autopilot, governed by the Dronecode Foundation',
  'MAVLink': 'the open messaging protocol most drones and ground stations speak',
  'EO/IR': 'electro-optical and infrared: day and thermal cameras',
  'NdFeB': 'neodymium-iron-boron: the rare-earth magnet inside most drone motors',
};
const GLOSS_RE = new RegExp('(^|[^A-Za-z0-9])(' + Object.keys(GLOSSARY)
  .sort((a, b) => b.length - a.length).map(k => k.replace(/[.*+?^${}()|[\]\\\/&]/g, '\\$&')).join('|') +
  ')(s?)(?![A-Za-z0-9])', 'g');
// first use of each term per block becomes <abbr>; text inside HTML tags is left alone
function gloss(html) {
  const seen = new Set();
  return String(html).split(/(<[^>]+>)/).map(part => part.startsWith('<') ? part :
    part.replace(GLOSS_RE, (m, pre, term, pl) => {
      if (seen.has(term)) return m;
      seen.add(term);
      return `${pre}<abbr title="${GLOSSARY[term].replace(/"/g, '&quot;')}">${term}${pl}</abbr>`;
    })).join('');
}

